create table if not exists public.state_rule_pack_candidates (
  id uuid primary key default gen_random_uuid(),
  state_code text not null check (state_code ~ '^[A-Z]{2}$'),
  inventory_generated_at timestamptz not null,
  status text not null default 'queued_for_agent_verification'
    check (status in ('queued_for_agent_verification','agent_verification_in_progress','blocked','verified','rejected')),
  source_candidate_count integer not null check (source_candidate_count > 0),
  blocked_source_count integer not null default 0 check (blocked_source_count >= 0 and blocked_source_count <= source_candidate_count),
  candidate_manifest jsonb not null,
  agent_verification_required boolean not null default true,
  compliance_activation_allowed boolean not null default false check (compliance_activation_allowed = false),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (state_code, inventory_generated_at)
);

create table if not exists public.state_rule_source_candidates (
  id uuid primary key default gen_random_uuid(),
  state_code text not null check (state_code ~ '^[A-Z]{2}$'),
  inventory_generated_at timestamptz not null,
  scope text not null,
  authority_name text not null,
  official_domain text not null,
  origin_file text not null,
  program text not null,
  source_type text not null,
  source_url text not null check (source_url ~ '^https://'),
  candidate_status text not null,
  agent_verification_status text not null default 'queued_for_agent_verification'
    check (agent_verification_status in ('queued_for_agent_verification','fetching','captured_unvalidated','blocked','verified','rejected')),
  exact_bytes_captured boolean not null default false,
  compliance_activation_allowed boolean not null default false check (compliance_activation_allowed = false),
  source_sha256 text check (source_sha256 is null or source_sha256 ~ '^[0-9a-f]{64}$'),
  retrieved_at timestamptz,
  verification_evidence jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (state_code, inventory_generated_at, scope, source_url),
  foreign key (state_code, inventory_generated_at)
    references public.state_rule_pack_candidates(state_code, inventory_generated_at)
    on delete restrict
);

create index if not exists state_rule_pack_candidates_queue_idx
  on public.state_rule_pack_candidates(status, state_code);
create index if not exists state_rule_source_candidates_queue_idx
  on public.state_rule_source_candidates(agent_verification_status, state_code, source_type);

alter table public.state_rule_pack_candidates enable row level security;
alter table public.state_rule_source_candidates enable row level security;

grant select on public.state_rule_pack_candidates, public.state_rule_source_candidates to authenticated;
grant all on public.state_rule_pack_candidates, public.state_rule_source_candidates to service_role;

drop policy if exists "Staff can view state pack candidates" on public.state_rule_pack_candidates;
create policy "Staff can view state pack candidates"
  on public.state_rule_pack_candidates for select to authenticated
  using (public.has_role(auth.uid(), 'staff'::public.app_role));

drop policy if exists "Staff can view state source candidates" on public.state_rule_source_candidates;
create policy "Staff can view state source candidates"
  on public.state_rule_source_candidates for select to authenticated
  using (public.has_role(auth.uid(), 'staff'::public.app_role));

