on conflict (state_code, inventory_generated_at, scope, source_url) do update set
  authority_name=excluded.authority_name,
  official_domain=excluded.official_domain,
  origin_file=excluded.origin_file,
  program=excluded.program,
  source_type=excluded.source_type,
  candidate_status=excluded.candidate_status,
  agent_verification_status=case
    when public.state_rule_source_candidates.agent_verification_status in ('verified','rejected') then public.state_rule_source_candidates.agent_verification_status
    else 'queued_for_agent_verification'
  end,
  updated_at=now();

comment on table public.state_rule_pack_candidates is
  'Fail-closed 50-state rule-pack candidate queue. Candidate presence never activates compliance rules.';
comment on table public.state_rule_source_candidates is
  'Official state-source candidates awaiting exact-byte capture, hashes, content validation, supersession reconciliation, deterministic fixtures, and independent approval.';
